          "detrimentText": "為了革命，耐性居次（忽略耐性）。\n更高層次的覺知無法等待，亟需表達達。",
          "weather": "今日的集體氣候圍繞著「接納---自我方向」展開；有些人會直接遇到事件，有些人則只是感到內在注意力被牽動。無論決定如何回應，接納是最根本的基礎，也是行動的根源。\n這股力量經過第3爻後，呈現出「試錯、碰撞與適應」的色彩，因此「耐性」不只是概念，也可能成為今天反覆出現的情境。\n老師是永不停止學習的學生。\n它較成熟的一面可能是：終身貢獻，成熟接受其過程永無止盡。當連接相對應的14號閘門，形成脈動的通道，服務會獲得報酬。\n瞭解接受是一生的歷程。\n需要留意的另一端則是：為求革命，耐性居次。更高層次的覺知無法等待，亟需表達。",
          "practice": "與其急著把今天過成某個標準答案，更適合從「耐性」開始觀察自己的反應。\n把變數當成資料，允許計畫在過程中被修正。這比急著回應外界氣氛，更能讓你看清流日正在放大什麼。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n今日能量可以成為觀察素材，但不要讓它替你做決定；你的策略與內在權威仍是主軸。"
