          "weather": "今天的外在程式把焦點落在「凡事起頭難---秩序」。它不一定製造事件，卻可能改變我們看待事件的角度。發起時所面對最根本的挑戰，來自於如何超越困惑，並建立秩序。\n第6爻替「凡事起頭難---秩序」加上一層「抽離、觀察與週期轉換」的視角，而爻名「投降」正好指出這一天最值得辨認的細節。\n最終的成熟是了解，掙扎是徒勞。\n在較穩定的表達裡，當光依舊閃耀，生命就會持續。\n天生就能接受秩序是過程，並非問題。\n壓力升高時，也可能出現：當黑暗覆沒，生命可能看似毫無價值而感到沮喪和絕望。\n困惑能量是壓倒性的力量，導致沮喪。",
          "practice": "今天可以少一點預設，多一點觀察。「投降」可能透過工作、人際或一個臨時變化讓你看見自己。\n比較合拍的做法是：先站遠一點看全局，讓經驗沉澱後再決定是否介入。若外界催促你加速，也先確認那是不是你的節奏。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n把它當成一日的環境提示即可。是否行動、何時行動，仍由你的策略與內在權威決定。"
