          "detrimentPlanet": "☉",
          "detrimentText": "對小孩無法放手的父母，覺得自身權威被挑戰。\n貢獻本身就是目的，並非接受或預見限制，例如：對孩子無法放手的父母。",
          "weather": "黑太陽來到\n8.5，像替集體打開一扇通往「凝聚在一起---貢獻」的門；相關的人事物更容易被看見。當個人致力為團體目標做出貢獻，其基本價值便得以展現。\n到了第5爻，重點不只在閘門本身，更落到「投射、期待與實際解方」；「達摩」是今天辨識能量走向的重要線索。\n齊聚-堂到最後，終究難逃分離。成功的結合代表著聚散終有時，幼鳥長成之後會離巢。這是正確的作為，無損於連結的本質。\n它較成熟的一面可能是：老師。接受並了解限制，於教學中驗證，並分享這過程，而貢獻則涵蓋於其中。\n需要留意的另一端則是：那些對小孩無法放手的父母，只知道自己的權威受到挑戰。不願接受，亦無法預見限制，無法對孩子放手，父母本身就是例證，不言而明，其結果即是貢獻。",
          "practice": "與其急著把今天過成某個標準答案，更適合從「達摩」開始觀察自己的反應。\n分辨哪些期待值得承接，哪些只是別人投射過來的角色。這比急著回應外界氣氛，更能讓你看清流日正在放大什麼。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n今日能量可以成為觀察素材，但不要讓它替你做決定；你的策略與內在權威仍是主軸。"
