          "practice": "今天可以少一點預設，多一點觀察。「現實主義」可能透過工作、人際或一個臨時變化讓你看見自己。\n比較合拍的做法是：分辨哪些期待值得承接，哪些只是別人投射過來的角色。若外界催促你加速，也先確認那是不是你的節奏。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n把它當成一日的環境提示即可。是否行動、何時行動，仍由你的策略與內在權威決定。"
