          "weather": "進入 20.6\n的流日時段後，「注視---當下」像一股底色滲進日常，影響人們如何回應眼前的情境。當下的識別與覺察，將理解轉化為適切的行動。\n第6爻替「注視---當下」加上一層「抽離、觀察與週期轉換」的視角，而爻名「智慧」正好指出這一天最值得辨認的細節。\n沉思，才能具備運用所知的能力。\n當這股能量找到合適出口時，基於社會福祉，價值，理想與大眾的模式而創立體制，以大眾能了解並運用的方式，與之溝通。有能力轉化個人覺知，使之普及運用並被大眾所理解。\n相對地，今天的陰影面可能表現在：與上述相同，只是其出發點，是為了挑戰智識層面，因而獲得自我的滿足，而非利他。為了智識層面的挑戰，而轉化個人覺知，為大眾所運用。",
          "practice": "今天的練習不是完成「智慧」，而是辨認它何時自然出現在你的生活裡。\n實際上，可以試著先站遠一點看全局，讓經驗沉澱後再決定是否介入。重點不是做得完美，而是保留足夠空間辨認自己的真實回應。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n今日能量可以成為觀察素材，但不要讓它替你做決定；你的策略與內在權威仍是主軸。"
