          "weather": "今天的外在程式把焦點落在「優雅---開放」。它不一定製造事件，卻可能改變我們看待事件的角度。在處理世俗瑣事時，展現出極具質感的行為。\n第1爻替「優雅---開放」加上一層「奠基、內省與安全感」的視角，而爻名「次等艙」正好指出這一天最值得辨認的細節。\n在較穩定的表達裡，其能力在於，能接受並享受自己為人部屬。在情感上，察覺自己喜愛處於下屬的位置。\n壓力升高時，也可能出現：手持次等艙機票，聲稱要坐頭等的位置，將不可避免招來羞辱。當情緒化的能量，挑戰約定俗成的默契，於社交層面帶來屈辱。",
          "practice": "若想把這股流日用在日常，可以先問自己：此刻的「次等艙」是自然發生，還是我正在用力製造？\n實際上，可以試著先把根基摸清楚，再決定是否向外推進。重點不是做得完美，而是保留足夠空間辨認自己的真實回應。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n你可以感受這股氣候，卻不必服從它。最終仍以自己的策略與內在權威作為決策依據。"
