          "practice": "今天的練習不是完成「靈敏度」，而是辨認它何時自然出現在你的生活裡。\n實際上，可以試著從熟悉的人際網絡與既有連結中觀察影響如何擴散。重點不是做得完美，而是保留足夠空間辨認自己的真實回應。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n你可以感受這股氣候，卻不必服從它。最終仍以自己的策略與內在權威作為決策依據。"
