          "detrimentPlanet": "♂",
          "detrimentText": "總會出現尶尬的場面，最後不可避免地被歸類為粗魯失禮。\n個人行為在社交層面，有可能引來負面的投射。",
          "weather": "當黑太陽行經\n22.5，今天的集體場域像是換了一層濾鏡：「優雅---開放」成為較醒目的背景音。在處理世俗瑣事時，展現出極具質感的行為。\n而第5爻讓這個主題進入「投射、期待與實際解方」的運作層次，本爻以「直接」點出關鍵。\n我行我素，不拘泥於形式。\n在較穩定的表達裡，承襲更高原則的力量，超脫約定俗成的行為準則。有可能透過情緒的察覺，在社交上充分展現其個性。\n壓力升高時，也可能出現：總會製造出尷尬的場面，然後也總會成功地，獲得粗魯與無理的名聲。其個人的行為，有可能會在社交與互動間，引來別人負面的投射。",
          "practice": "若今天某件事讓你特別在意，先別急著處理結果；看看「直接」是否正在揭露其中真正的課題。\n今天尤其適合分辨哪些期待值得承接，哪些只是別人投射過來的角色。把注意力放在過程，而不是急著證明自己已經得到答案。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n流日提供的是天氣，不是命令；真正的決定仍回到你自己的策略與內在權威。"
