          "detrimentPlanet": "♂",
          "detrimentText": "不再墨守成規，傾向表現自我。\n在社交層面的經驗，引發開放的可能性，表達方式跳脫約定俗成的規範。",
          "weather": "今天的流日把「優雅---開放」推到前景，空氣裡容易浮現與它相關的議題。在處理世俗瑣事時，展現出極具質感的行為。\n這股力量經過第6爻後，呈現出「抽離、觀察與週期轉換」的色彩，因此「成熟」不只是概念，也可能成為今天反覆出現的情境。\n在實質的層面，整合形式所帶來的體驗。\n順勢時，與生俱來，自然而顯著的領導能力和權威感。基於社交互動層面的經驗值，因而培養出領導力的可能。\n若能量失衡，可能滑向：其行為的表現，具備不再循規蹈矩的傾向，以此來調整。在社交層面的體驗，將引發開放的可能，其表達方式將跳脫既定俗成的規範。",
