          "detrimentPlanet": "☽",
          "detrimentText": "木星要忠於本性，所以防衛的最佳方式是攻擊。而月亮則是排除敵意，保護好自己就好了。\n面對敵意，戒慎防衛，表達中有所保留。",
          "weather": "今天的外在程式把焦點落在「裂開---同化」。它不一定製造事件，卻可能改變我們看待事件的角度。超越道德。察覺與認知，得以接納多元性。\n第2爻替「裂開---同化」加上一層「自然展露、隱退與被看見」的視角，而爻名「自衛」正好指出這一天最值得辨認的細節。\n當生存備受威脅，無須繼續忍耐。\n在較穩定的表達裡，緊要關頭的最終保護原則。當個體化的表達遭受威脅，孰不可忍。\n壓力升高時，也可能出現：木星在此，採取重拳出擊的方式來防衛，以求能忠於本性。而月亮只要能排除敵意，保護好自己，就會感到滿足。面對敵意時，戒慎防衛，其表達中帶有保留。",
          "practice": "今天可以少一點預設，多一點觀察。「自衛」可能透過工作、人際或一個臨時變化讓你看見自己。\n比較合拍的做法是：不必刻意表現，讓適合的人事物來敲門。若外界催促你加速，也先確認那是不是你的節奏。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n你可以感受這股氣候，卻不必服從它。最終仍以自己的策略與內在權威作為決策依據。"
