          "exaltPlanet": "☉",
          "exaltText": "個人的活力與力量，容易招來妒忌，還不至於構成威脅。\n充滿個性的表達，引來注意力，而非威脅。",
          "detrimentPlanet": "♇",
          "detrimentText": "個體的神秘性，招來猜疑與威脅。\n怪胎。充滿個人色彩的表達方式，引發猜忌與威脅。",
          "weather": "如果今天有某些情境格外抓住注意力，可以看看它是否正呼應「裂開---同化」的主題。超越道德。察覺與認知，得以接納多元性。\n到了第3爻，重點不只在閘門本身，更落到「試錯、碰撞與適應」；「個體性」是今天辨識能量走向的重要線索。\n基於本性而傳達其個體性，對別人無害。\n順勢時，活力與個人的力量會招來忌妒，但不至於形成威脅。充滿個性的表達會吸引來注意力，而非威脅。\n若能量失衡，可能滑向：個體的神秘性主動招來猜疑與威脅。怪胎。個人化的表達方式，吸引猜忌與威脅。",
          "practice": "今天的練習不是完成「個體性」，而是辨認它何時自然出現在你的生活裡。\n實際上，可以試著把變數當成資料，允許計畫在過程中被修正。重點不是做得完美，而是保留足夠空間辨認自己的真實回應。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n把它當成一日的環境提示即可。是否行動、何時行動，仍由你的策略與內在權威決定。"
