          "weather": "今日的集體氣候圍繞著「偉大的馴服力---利己主義者」展開；有些人會直接遇到事件，有些人則只是感到內在注意力被牽動。讓記憶發揮最大的力量，運用於長程持續的培育。\n這股力量經過第3爻後，呈現出「試錯、碰撞與適應」的色彩，因此「影響力」不只是概念，也可能成為今天反覆出現的情境。\n有能力蓄勢待發，獲得支持。\n它較成熟的一面可能是：得以集結眾人之力的權威。發揮意志力的力量，集結支持。\n需要留意的另一端則是：其領導力在集結支持時，低估潜在的挑戰。利己主義者，無法理解他人可能帶來的挑戰。",
          "practice": "與其急著把今天過成某個標準答案，更適合從「影響力」開始觀察自己的反應。\n把變數當成資料，允許計畫在過程中被修正。這比急著回應外界氣氛，更能讓你看清流日正在放大什麼。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n你可以感受這股氣候，卻不必服從它。最終仍以自己的策略與內在權威作為決策依據。"
