          "detrimentText": "當改變本質是必要的下一步，將引發抗拒與不滿。\n利己主義者對適應本身，心懷抗拒。",
          "weather": "今天的外在程式把焦點落在「偉大的馴服力---利己主義者」。它不一定製造事件，卻可能改變我們看待事件的角度。讓記憶發揮最大的力量，運用於長程持續的培育。\n第5爻替「偉大的馴服力---利己主義者」加上一層「投射、期待與實際解方」的視角，而爻名「適應力」正好指出這一天最值得辨認的細節。\n在較穩定的表達裡，瞭解整體機制如何運轉，懂得運用能量，以求將潛能極大化。記憶的力量，能將意志力的潛能極大化，吸引他人。\n壓力升高時，也可能出現：當改變本質是必要的下一步，將引發抗拒與不滿。利己主義者對適應本身，心生抗拒。",
          "practice": "若想把這股流日用在日常，可以先問自己：此刻的「適應力」是自然發生，還是我正在用力製造？\n實際上，可以試著分辨哪些期待值得承接，哪些只是別人投射過來的角色。重點不是做得完美，而是保留足夠空間辨認自己的真實回應。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n今日能量可以成為觀察素材，但不要讓它替你做決定；你的策略與內在權威仍是主軸。"
