          "weather": "如果今天有某些情境格外抓住注意力，可以看看它是否正呼應「偉大的馴服力---利己主義者」的主題。讓記憶發揮最大的力量，運用於長程持續的培育。\n到了第6爻，重點不只在閘門本身，更落到「抽離、觀察與週期轉換」；「權威」是今天辨識能量走向的重要線索。\n以確切的行動，來合理化天生的影響力。\n順勢時，通過時間的考驗，將理由與目的具體化。強大自我的影響力，基於所採取的正確行動，因而獲得合理化。\n若能量失衡，可能滑向：權威是象徵也是焦點所在，卻不等同於具體實踐方案。君主立憲政體，就算卸下實權，依舊象徵權威之延續。意志力的表現，其角色所帶來的影響力，往往缺乏權威，徒留象徵的意義。",
          "practice": "今天不妨把「權威」當成一面鏡子：遇到事情時，先看自己正被什麼牽動。\n先站遠一點看全局，讓經驗沉澱後再決定是否介入。這比急著回應外界氣氛，更能讓你看清流日正在放大什麼。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n你可以感受這股氣候，卻不必服從它。最終仍以自己的策略與內在權威作為決策依據。"
