          "exaltText": "即便在變化的時代，特定的基本規則仍適用。\n在變動時期，堅守個人原則的本能。",
          "detrimentPlanet": "♄",
          "detrimentText": "木星在上升相位，將在更廣泛的社交領域，奠定正確的行動。土星只要不被外在所威脅，就能引發出內在的力量與持久力。\n只要不危及個人安全，保有個人原則是天性。",
          "weather": "如果今天有某些情境格外抓住注意力，可以看看它是否正呼應「持久---連續」的主題。唯一不變的就是改變\n這股力量經過第4爻後，呈現出「關係、固定模式與影響力」的色彩，因此「強權即公理」不只是概念，也可能成為今天反覆出現的情境。\n順勢時，人即便在變化的時代，特定的基本規則仍然適用。在變動時期，堅守個人原則的本能。\n若能量失衡，可能滑向：木星在此，將會在更廣闊的社交領域範圍中，奠定正確的行動，而土星只要不被外在所威脅，就能引發出內在的力量與持久力。只要不危及個人安全，保有個人原則是天性。",
          "practice": "把「強權即公理」放進今天的生活，不需要刻意安排事件；留意它在哪些選擇、對話與情緒裡冒出來即可。\n比較合拍的做法是：從熟悉的人際網絡與既有連結中觀察影響如何擴散。若外界催促你加速，也先確認那是不是你的節奏。\n如果互動變得自然、事情不用硬推就能前進，這通常比『做對了沒有』更值得觀察。\n反過來，若開始急著證明、控制或硬撐，可以把那份不舒服當成提醒，看看是否只是被今日場域放大。\n流日提供的是天氣，不是命令；真正的決定仍回到你自己的策略與內在權威。"
