          "weather": "這一天的氣氛，未必喧鬧，卻會反覆把人帶回「持久---連續」這個核心。唯一不變的就是改變\n第6爻替「持久---連續」加上一層「抽離、觀察與週期轉換」的視角，而爻名「安然以對」正好指出這一天最值得辨認的細節。\n面對無常，安然以對是必要的。\n當這股能量找到合適出口時，底層對改變抱持接受的態度，不管最後是否能感到平靜。出於本能的覺知，接受改變與蛻變。\n相對地，今天的陰影面可能表現在：以無常來證明這一切毫無意義，伴隨而來的表現是抑鬱，妄想，以及走至極端，自我毀滅。若將改變的體驗視為無常，恐懼因而產生，有可能因而深陷沮喪之中。",
          "practice": "面對今天的節奏，「安然以對」比較像提醒標誌，而不是待辦事項。\n今天尤其適合先站遠一點看全局，讓經驗沉澱後再決定是否介入。把注意力放在過程，而不是急著證明自己已經得到答案。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n把它當成一日的環境提示即可。是否行動、何時行動，仍由你的策略與內在權威決定。"
