          "weather": "今天的外在程式把焦點落在「強大的能量---力量」。它不一定製造事件，卻可能改變我們看待事件的角度。當力量被展現及運用在共同利益上，才會顯現其偉大。\n而第5爻讓這個主題進入「投射、期待與實際解方」的運作層次，本爻以「殲滅」點出關鍵。\n將阻力徹底排除。\n在較穩定的表達裡，徹底摧毀的力量，一旦完成之後，將這股力量轉換為一般用途的能力。除非必要，否則對釋放力量有所抗拒。\n壓力升高時，也可能出現：相當困難，面對阻力，崩解已建立的模式。在此階段象徵著，沒有什麼能永遠被消滅。對於不時需要展現力量的狀態，並不自在。",
