          "weather": "如果今天有某些情境格外抓住注意力，可以看看它是否正呼應「強大的能量---力量」的主題。當力量被展現及運用在共同利益上，才會顯現其偉大。\n這股力量經過第6爻後，呈現出「抽離、觀察與週期轉換」的色彩，因此「常識」不只是概念，也可能成為今天反覆出現的情境。\n知道適可而止。\n順勢時，當承受過多時，懂得如何捨棄的智慧。無法維持，感覺後繼無力時，懂得管制並收起自身的力量。\n若能量失衡，可能滑向：熱心過頭，以致無法做出較好的判斷，導致橫生枝節。若不知節制，將耗損其力量。",
