          "weather": "今天的流日把「聚合---警覺」推到前景，空氣裡容易浮現與它相關的議題。不帶有任何前提與條件，就是互動得以成功的基礎。\n這股力量經過第4爻後，呈現出「關係、固定模式與影響力」的色彩，因此「誠實」不只是概念，也可能成為今天反覆出現的情境。\n拒絕虛偽的互動模式。\n順勢時，事不關己，以最邏輯的方式切割。以其本能與經驗值為準則，冷漠的可能性。\n若能量失衡，可能滑向：太陽在下降相位，若身處極端狀態下，為求維生，會期待能自過往的拒絕往來戶中，重新取得支援。真誠是最好的作法，誠實以對。為了求存，不再冷漠。",
