          "exaltText": "獲得好運的實際作法，延續既定的成功模式與態度，而非迷失在未來的期待中，而誤入歧途。\n決心，堅持既定的成功要素。",
          "detrimentPlanet": "♂",
          "detrimentText": "基於投射的傾向，將未來有可能會發生的一切，當成現實，導致偏頗的利己主義，會逐步失去原有的動能與支持。\n決定要將預期中的成功，當成現實。",
          "weather": "黑太陽來到\n46.3，像替集體打開一扇通往「推進---自我決心」的門；相關的人事物更容易被看見。好運源於因緣俱足，一切來自於努力與奉獻。\n第3爻替「推進---自我決心」加上一層「試錯、碰撞與適應」的視角，而爻名「投射」正好指出這一天最值得辨認的細節。\n它較成熟的一面可能是：通往好運的實際作法，是延續既定的成功模式與態度，而非迷失在未來的期望之中，因而誤入歧途。有決心堅持既定的成功要素。\n需要留意的另一端則是：基於投射的傾向，將未來有可能發生的一切，當成現況，導致偏頗的利己主義，逐步失去動能和支持。決定將預設的成功，當成實際的狀況。",
