          "weather": "今天的外在程式把焦點落在「壓抑---了解」。它不一定製造事件，卻可能改變我們看待事件的角度。限制與逆境來自於內在的軟弱或外來力量，或來自兩者。\n第2爻替「壓抑---了解」加上一層「自然展露、隱退與被看見」的視角，而爻名「野心」正好指出這一天最值得辨認的細節。\n在較穩定的表達裡，為求安全，深具企圖心與驅動力，渴望克服自身的苦惱。理解忙碌能讓人心智健康。\n壓力升高時，也可能出現：面對個人的苦惱時，優柔寡斷，猶豫不決，無法決定該運用智慧而釋懷，還是善用可能會稍縱即逝的優勢，接受苦惱的重擔。無法分辨何時與何種行動，才是健康的舉動。",
          "practice": "今天可以少一點預設，多一點觀察。「野心」可能透過工作、人際或一個臨時變化讓你看見自己。\n比較合拍的做法是：不必刻意表現，讓適合的人事物來敲門。若外界催促你加速，也先確認那是不是你的節奏。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n把它當成一日的環境提示即可。是否行動、何時行動，仍由你的策略與內在權威決定。"
