          "practice": "今天可以少一點預設，多一點觀察。「微不足道」可能透過工作、人際或一個臨時變化讓你看見自己。\n比較合拍的做法是：先把根基摸清楚，再決定是否向外推進。若外界催促你加速，也先確認那是不是你的節奏。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n把它當成一日的環境提示即可。是否行動、何時行動，仍由你的策略與內在權威決定。"
