          "detrimentPlanet": "☿",
          "detrimentText": "若具有深度的智慧，就此散佚於荒野，將引發出深層的焦慮。\n面對長期的過程（品味與深度的養成），感到焦慮的傾向。",
          "weather": "今天的外在程式把焦點落在「井---深度」。它不一定製造事件，卻可能改變我們看待事件的角度。建立共同利益的先決條件，須有必要性與本質上的基礎。\n第3爻替「井---深度」加上一層「試錯、碰撞與適應」的視角，而爻名「單獨監禁」正好指出這一天最值得辨認的細節。\n在較穩定的表達裡，以「朔月」作為此階段的象徵，潛在光明尚不可識別、不可用、不可知。頃刻之間，此階段有其救贖的價值，能讓那些備受折磨的人，重新獲得力量。品味與深度需要長期養成。\n壓力升高時，也可能出現：若讓極具深度的智慧，就此散佚於荒野，將引發出深層的焦慮。面對長期的過程（品味與深度的養成），感到焦慮的傾向。",
          "practice": "若今天某件事讓你特別在意，先別急著處理結果；看看「單獨監禁」是否正在揭露其中真正的課題。\n今天尤其適合把變數當成資料，允許計畫在過程中被修正。把注意力放在過程，而不是急著證明自己已經得到答案。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n你可以感受這股氣候，卻不必服從它。最終仍以自己的策略與內在權威作為決策依據。"
