          "weather": "如果今天有某些情境格外抓住注意力，可以看看它是否正呼應「井---深度」的主題。建立共同利益的先決條件，須有必要性與本質上的基礎。\n到了第4爻，重點不只在閘門本身，更落到「關係、固定模式與影響力」；「重建」是今天辨識能量走向的重要線索。\n順勢時，有良好的判斷力，善用短程活動，以有限的規模先行測試，評估情勢並作調整，如此可為長期目標奠定基礎，有助於在未來推行活動時，一切能進展得更順利。察覺到深度本身與其展現的可能，考慮未來面對限制在所難免，退而偏向執行短期計畫。\n若能量失衡，可能滑向：對於在不確定的狀態下重整，心懷抗拒，傾向抱持著船到橋頭自然直的想法。偏向長期計畫，經歷限制而感到挫敗。",
          "practice": "把「重建」放進今天的生活，不需要刻意安排事件；留意它在哪些選擇、對話與情緒裡冒出來即可。\n比較合拍的做法是：從熟悉的人際網絡與既有連結中觀察影響如何擴散。若外界催促你加速，也先確認那是不是你的節奏。\n當你感到事情有流動感時，留意那是否正呼應本爻較順勢的表達。\n遇到阻力時，先別急著修正自己；有時那只是這條爻的另一極被環境暫時放大。\n流日提供的是天氣，不是命令；真正的決定仍回到你自己的策略與內在權威。"
