          "weather": "這一天的氣氛，未必喧鬧，卻會反覆把人帶回「激起---衝擊」這個核心。透過了解與適應，回應混亂和衝擊的能力。\n第1爻替「激起---衝擊」加上一層「奠基、內省與安全感」的視角，而爻名「參考」正好指出這一天最值得辨認的細節。\n過往處理危機的經驗值，成為優勢。\n當這股能量找到合適出口時，具備重複檢視的天賦，這是預作準備的基礎。自我的力量，受經驗所制約。\n相對地，今天的陰影面可能表現在：震驚之後，在情緒層面退縮的傾向。面對挑戰時，自我的弱點。",
