          "detrimentText": "當一個人的日常作息被擾亂，呈現不穩定的狀態，會傾向退縮，而非適應。\n面對挑戰時，自我可能就此動搖。",
          "weather": "今天的流日把「激起---衝擊」推到前景，空氣裡容易浮現與它相關的議題。透過了解與適應，回應混亂和衝擊的能力。\n而第3爻讓這個主題進入「試錯、碰撞與適應」的運作層次，本爻以「適應」點出關鍵。\n順勢時，為維繫生命，於意識層面隨機應變，創造機會。面對挑戰時，自發的力量。\n若能量失衡，可能滑向：若日常作息面對突如其來的干擾，因而大亂，導致不穩定，會傾向退縮，而非適應。面對挑戰時，自我可能會因而動搖。",
