          "detrimentText": "令人好奇的是，同樣的天賦，有些人的態度反倒引來非難，甚至更極端的狀態，無法成功抽離。\n獨自面對挑戰的自我主義者，反倒激怒或鼓動更多挑戰者。",
          "weather": "今天的外在程式把焦點落在「激起---衝擊」。它不一定製造事件，卻可能改變我們看待事件的角度。透過了解與適應，回應混亂和衝擊的能力。\n第6爻替「激起---衝擊」加上一層「抽離、觀察與週期轉換」的視角，而爻名「分割」正好指出這一天最值得辨認的細節。\n在較穩定的表達裡，面對危機時，當眾人皆感到困惑且失序，不但具備處變不驚的能力，同時還能秉持其意志力與活力，獨立自主，找到生存之道。源於自我的力量，以一己之力迎向挑戰。\n壓力升高時，也可能出現：令人好奇的是，同樣的天賦，有些人的態度反倒招來非難，處於更極端的狀態，甚至無法成功脫離。獨自面對挑戰的自我主義者，可能會激怒或鼓動挑戰者。",
          "practice": "今天可以少一點預設，多一點觀察。「分割」可能透過工作、人際或一個臨時變化讓你看見自己。\n比較合拍的做法是：先站遠一點看全局，讓經驗沉澱後再決定是否介入。若外界催促你加速，也先確認那是不是你的節奏。\n若事情自然展開，可以觀察原爻辭所描述的順勢面如何在具體情境中出現，而不必刻意追求它。\n若卡住的感覺變強，不必立刻把它解釋成失敗；先辨認自己是不是正在替流日的壓力做決定。\n今日能量可以成為觀察素材，但不要讓它替你做決定；你的策略與內在權威仍是主軸。"
