          "weather": "如果今天有某些情境格外抓住注意力，可以看看它是否正呼應「內在真裡---神秘」的主題。察覺普世運作的基本原則。\n而第1爻讓這個主題進入「奠基、內省與安全感」的運作層次，本爻以「奧祕知識」點出關鍵。\n順勢時，天生具有靈性洞察力，賦予普世原則。內在感到壓力，渴望透過祕傳之道，知曉奧秘。\n若能量失衡，可能滑向：若仰賴神的知識，需要不斷抽離與苦行，最終依舊隱晦難明。在此承受巨大壓力，終究屈服於世俗與現實。",
