          "weather": "黑太陽來到\n61.2，像替集體打開一扇通往「內在真裡---神秘」的門；相關的人事物更容易被看見。察覺普世運作的基本原則。\n這股力量經過第2爻後，呈現出「自然展露、隱退與被看見」的色彩，因此「天生耀眼」不只是概念，也可能成為今天反覆出現的情境。\n它較成熟的一面可能是：月亮處於上升相位，如此才華洋溢，無遠弗屆，其影響力蘊含滋養，不要花招並具備強大的吸引力。啟迪眾人的天賦，不但具吸引力，同時也能利益他人。\n需要留意的另一端則是：太早得知其影響力，容易誇大而演變為自戀。充滿幻覺，認為任何啟發都將獲得肯定。",
