          "detrimentPlanet": "♇",
          "detrimentText": "為了對抗既定的價值觀，想要有所行動，卻受限於環境因素，於是轉為退縮，以等待時機。\n靜待細節彙整完畢前，孤立其實是策略，靜待表達的正確時機。",
          "weather": "這一天的氣氛，未必喧鬧，卻會反覆把人帶回「處理細節的優勢---細節」這個核心。謹慎、耐心和細節，得以超越極限，創造優越\n而第4爻讓這個主題進入「關係、固定模式與影響力」的運作層次，本爻以「苦行主義」點出關鍵。\n當這股能量找到合適出口時，以苦行撤離的完美方式，追求和諧與簡單，在此外界的危險不復存在，才有充裕的時間細細思索，追求內在的意義。所謂的細節，必須花時間，經歷隔離與反思的過程，才能真正表現出來。\n相對地，今天的陰影面可能表現在：為了對抗約定俗成的價值觀，渴望有所行動，當受限於環境因素，轉為退縮，以等待時機。當細節彙整完畢，孤立其實是策略運用，靜待表達的正確時機。",
          "practice": "今天的練習不是完成「苦行主義」，而是辨認它何時自然出現在你的生活裡。\n實際上，可以試著從熟悉的人際網絡與既有連結中觀察影響如何擴散。重點不是做得完美，而是保留足夠空間辨認自己的真實回應。\n如果互動變得自然、事情不用硬推就能前進，這通常比『做對了沒有』更值得觀察。\n反過來，若開始急著證明、控制或硬撐，可以把那份不舒服當成提醒，看看是否只是被今日場域放大。\n你可以感受這股氣候，卻不必服從它。最終仍以自己的策略與內在權威作為決策依據。"
